<script setup>import { Menu, ChevronDown, LogOut } from 'lucide-vue-next'; import ThemeToggle from './ThemeToggle.vue'; import AppDropdown from './ui/AppDropdown.vue'; defineProps({theme:String,user:Object,title:String}); const emit=defineEmits(['update:theme','logout','menu'])</script>
<template><header class="header"><div class="crumb"><button class="mobile-menu" @click="emit('menu')"><Menu :size="21"/></button><span>Admin</span><i>/</i><b>{{title}}</b></div><div class="header-right"><ThemeToggle :model-value="theme" @update:model-value="emit('update:theme',$event)"/><AppDropdown><template #trigger><span class="avatar">{{user.name?.split(' ').map(x=>x[0]).slice(0,2).join('')}}</span><span class="account-name">{{user.name}}</span><ChevronDown :size="15"/></template><button class="logout" @click="emit('logout')"><LogOut :size="16"/>Logout</button></AppDropdown></div></header></template>
